package com.guocheng.mediapocket;
import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;
public class ClawCompatibleNetworkTest {
 static void check(boolean b,String reason){if(!b)throw new AssertionError(reason);}
 static final class Server implements AutoCloseable{ServerSocket server;Thread worker;AtomicInteger count=new AtomicInteger();boolean drop;int status;volatile String request="";Server(boolean firstDrop,int code)throws Exception{drop=firstDrop;status=code;server=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));worker=new Thread(()->{while(!server.isClosed())try(Socket s=server.accept()){s.setSoTimeout(3000);StringBuilder headers=new StringBuilder();BufferedReader in=new BufferedReader(new InputStreamReader(s.getInputStream(),"US-ASCII"));String line;while((line=in.readLine())!=null&&!line.isEmpty())headers.append(line).append("\n");request=headers.toString();int n=count.incrementAndGet();if(drop&&n==1)continue;byte[] body="{\"id\":\"fixture\"}".getBytes("UTF-8");s.getOutputStream().write(("HTTP/1.1 "+status+" Fixture\r\nContent-Length: "+body.length+"\r\nConnection: close\r\nContent-Type: application/json\r\n\r\n").getBytes("US-ASCII"));s.getOutputStream().write(body);}catch(Exception e){if(!server.isClosed())throw new RuntimeException(e);}});worker.setDaemon(true);worker.start();}String url(){return "http://127.0.0.1:"+server.getLocalPort()+"/manifest.json";}public void close()throws Exception{server.close();worker.join(2000);}}
 public static void main(String[] args)throws Exception{
 check(ClawCompatibleNetwork.ipv4(Arrays.asList(InetAddress.getByName("::1"),InetAddress.getByName("127.0.0.1")),"fixture").size()==1,"IPv4 filters IPv6");
 boolean onlyV6=false;try{ClawCompatibleNetwork.ipv4(Collections.singletonList(InetAddress.getByName("::1")),"fixture");}catch(UnknownHostException e){onlyV6=true;}check(onlyV6,"IPv6-only DNS must not be presented as IPv4");
 check(ClawCompatibleNetwork.CLIENTS[2].connectionSpecs().get(0).tlsVersions().equals(Collections.singletonList(okhttp3.TlsVersion.TLS_1_2)),"exact TLS1.2 fallback");
 check(ClawCompatibleNetwork.CLIENTS[2].hostnameVerifier()==ClawCompatibleNetwork.BASE.hostnameVerifier(),"retain default hostname verification");
 java.io.IOException nested=new java.io.IOException("outer",new javax.net.ssl.SSLHandshakeException("closed https://private.test/token"));String summary=ClawCompatibleNetwork.reason(nested);check(summary.contains("SSLHandshakeException")&&!summary.contains("private.test"),"error causes shown without URL tokens");
 check(ClawCompatibleNetwork.handles("https://torrentclaw.com/api/stremio/manifest.json"),"configured API scope");check(ClawCompatibleNetwork.handles("https://sub.torrentclaw.com/manifest.json"),"subdomain scope");for(String u:new String[]{"https://torrentclaw.com.attacker.test/x","https://elsewhere.test/torrentclaw.com","https://torrentclaw.com@elsewhere.test/","file:///torrentclaw.com","https://mediafusionfortheweebs.midnightignite.me/manifest.json"})check(!ClawCompatibleNetwork.handles(u),"must leave other hosts unchanged");
 try(Server server=new Server(true,200)){String data=new String(ClawCompatibleNetwork.fetch(server.url(),true),"UTF-8");check(data.contains("fixture"),"recover after abrupt connection close");check(server.count.get()>=2&&server.count.get()<=6,"bounded attempts");check(server.request.startsWith("GET /manifest.json HTTP/1.1"),"force HTTP/1.1");check(server.request.toLowerCase(Locale.ROOT).contains("connection: close"),"avoid stale reusable connection");check(server.request.contains("Mozilla/5.0"),"standard UA");}
 try(Server server=new Server(false,403)){boolean rejected=false;try{ClawCompatibleNetwork.fetch(server.url(),true);}catch(IOException e){rejected=e.getMessage().equals("HTTP 403");}check(rejected,"do not retry HTTP permission denial");check(server.count.get()==1,"HTTP error is not a connection retry");}
 if(args.length>0){byte[] live=ClawCompatibleNetwork.bytes("https://torrentclaw.com/api/stremio/manifest.json");check(new String(live,"UTF-8").contains("com.torrentclaw.addon"),"live manifest identity");System.out.println("PASS: live public manifest through compatibility client, "+live.length+" bytes.");
 okhttp3.Call tlsCall=ClawCompatibleNetwork.CLIENTS[2].newCall(new okhttp3.Request.Builder().url("https://torrentclaw.com/api/stremio/manifest.json").header("Connection","close").build());tlsCall.timeout().timeout(10,java.util.concurrent.TimeUnit.SECONDS);try(okhttp3.Response response=tlsCall.execute()){check(response.code()==200,"live TLS1.2 HTTP status");check(response.handshake()!=null&&response.handshake().tlsVersion()==okhttp3.TlsVersion.TLS_1_2,"real TLS1.2 negotiation");System.out.println("PASS: live TLS1.2 fallback negotiates TLS1.2 and returns HTTP200 with platform certificate checks.");}}
 System.out.println("PASS: real local socket close recovery, HTTP/1.1, bounded retries, 403 preserved and other hosts excluded.");System.exit(0);
 }
}
